    ])
  } catch (error) {
    await stop()
    if (error instanceof EngineStartError) throw error
    throw new EngineStartError("launch", "OpenCode startup failed", owned.pid)
  } finally {
    if (timer !== undefined) clearTimeout(timer)
  }
}

